new:
var DUAL_STICKER_W_MM = 120;
var DUAL_STICKER_H_MM = 50;
var DUAL_TAG_GAP_MM = 2;
/** One barcode print box on 120×50 butterfly tag: 2 cm × 2.5 cm */
var DUAL_QUADRANT_W_MM = 20;
var DUAL_QUADRANT_H_MM = 25;
function getDualHalfLabelWidthMm() {
    return (DUAL_STICKER_W_MM - DUAL_TAG_GAP_MM) / 2;
}
function getDualTagPrintBoxWidthMm() {
    return DUAL_QUADRANT_W_MM;
}
function getDualTagPrintBoxHeightMm() {
    return DUAL_QUADRANT_H_MM;
}
